### Code Snippets

```
// Create a vector called cars that will store strings
vector<string> cars = {"Volvo", "BMW", 
  "Ford", "Mazda"};
// Create a vector iterator 
  called it
vector<string>::iterator it;
// Loop through the vector with the 
  iterator
for (it = cars.begin(); it != cars.end(); ++it) {
cout << *it << 
  "\n";
}

